#include <list>
#include <iostream>

int main() {
    std::list<int> L1 = {1, 2, 3};
    std::list<int> L2 = {10, 20};

    // Get iterator to element '2'
    auto it_2 = std::next(L1.begin()); 

    // Move '2' from L1 to the start of L2
    L2.splice(L2.begin(), L1, it_2); 

    // L1 is now {1, 3}. L2 is {2, 10, 20}

    // The iterator is still valid and points to the element '2'
    // now residing in L2.
    std::cout << "Moved element: " << *it_2 << "\n"; 
}
